    validateProfile({ displayName: '   ', email: 'person@example.com' }),
    ['Display name is required.'],
  );
});

test('accepts a valid profile', () => {
  assert.deepEqual(
    validateProfile({ displayName: 'Ada', email: 'ada@example.com' }),
    [],
  );
});

